t.script:

(function() {
    // Prevent script from executing during PDF generation
    if (window.location.search.indexOf('readonly=') !== -1 && window.location.search.indexOf('pdf') !== -1) {
        return;
    }

    const originalPrint = window.print;

    function showModal() {
        const modal = document.getElementById('print-options-modal');
        if (modal) {
            modal.style.display = 'flex';
        }
    }

    function hideModal() {
        const modal = document.getElementById('print-options-modal');
        if (modal) {
            modal.style.display = 'none';
        }
    }

    window.print = function() {
        showModal();
    };

    function hookParentPrintButton() {
        try {
            if (!window.parent || !window.parent.document) return;

            const parentDoc = window.parent.document;
            const findAndHook = () => {
                const buttons = parentDoc.querySelectorAll('.o_control_panel button, .o_control_panel .btn');
                let printBtn = null;
                for (const btn of buttons) {
                    if (btn.textContent.trim().toLowerCase() === 'print' || btn.getAttribute('title') === 'Print') {
                        printBtn = btn;
                        break;
                    }
                }

                if (printBtn && !printBtn.dataset.hooked) {
                    printBtn.dataset.hooked = "true";
                    printBtn.addEventListener('click', function(e) {
                        e.stopPropagation();
                        e.preventDefault();
                        showModal();
                    }, true);
                    return true;
                }
                return false;
            };

            if (findAndHook()) return;

            let attempts = 0;
            const interval = setInterval(() => {
                attempts++;
                if (findAndHook() || attempts > 50) {
                    clearInterval(interval);
                }
            }, 100);
        } catch (e) {
            console.error("Error hooking parent print button:", e);
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        hookParentPrintButton();

        document.getElementById('btn-close-modal').addEventListener('click', hideModal);
        document.querySelector('.modal-backdrop').addEventListener('click', hideModal);

        function getEmployeeIds() {
            const articleElements = document.querySelectorAll('.article');
            const employeeIds = [];
            articleElements.forEach(function(el) {
                const id = el.getAttribute('data-oe-id');
                if (id) {
                    employeeIds.push(id);
                }
            });
            return employeeIds;
        }

        function triggerDownload(printSide) {
            hideModal();
            const employeeIds = getEmployeeIds();
            if (employeeIds.length > 0) {
                const url = '/report/pdf/hr_employee_id_card.report_employee_id_card_template/' + employeeIds.join(',');
                const type = 'qweb-pdf';
                let downloadUrl = '/report/download?data=' + encodeURIComponent(JSON.stringify([url, type]));
                if (printSide) {
                    downloadUrl += '&print_side=' + printSide;
                }
                window.location.href = downloadUrl;
            } else {
                alert("No employee records found to download PDF.");
            }
        }

        document.getElementById('btn-print-front').addEventListener('click', function() {
            triggerDownload('front');
        });

        document.getElementById('btn-print-back').addEventListener('click', function() {
            triggerDownload('back');
        });

        document.getElementById('btn-download-pdf').addEventListener('click', function() {
            triggerDownload(null);
        });
    });
})();
